pub(super) const TRIANGLES_GEOMETRYSHADERCODE_GS_LINES_CODE: &str = "uniform ivec2 renderingTargetSize;\n\nin  vec4 vs_gs_color[N_VERTICES];\nout vec4 gs_fs_color;\n\nvoid main()\n{\n    float dx = 2.0 / float(renderingTargetSize.x);\n    float dy = 2.0 / float(renderingTargetSize.y);\n\n    vec2 min_xy = gl_in[N_VERTEX0].gl_Position.xy;\n    vec2 max_xy = gl_in[N_VERTEX0].gl_Position.xy;\n\n    min_xy[0] = min(gl_in[N_VERTEX1].gl_Position.x, min_xy[0]);\n    min_xy[0] = min(gl_in[N_VERTEX2].gl_Position.x, min_xy[0]);\n    min_xy[1] = min(gl_in[N_VERTEX1].gl_Position.y, min_xy[1]);\n    min_xy[1] = min(gl_in[N_VERTEX2].gl_Position.y, min_xy[1]);\n\n    max_xy[0] = max(gl_in[N_VERTEX1].gl_Position.x, max_xy[0]);\n    max_xy[0] = max(gl_in[N_VERTEX2].gl_Position.x, max_xy[0]);\n    max_xy[1] = max(gl_in[N_VERTEX1].gl_Position.y, max_xy[1]);\n    max_xy[1] = max(gl_in[N_VERTEX2].gl_Position.y, max_xy[1]);\n\n    for (int n = 0; n < 3 ; ++n)\n    {\n        float hor_line_delta = 0.0;\n        float ver_line_delta = 0.0;\n\n        switch(n)\n        {\n            case 0: hor_line_delta = -dx; ver_line_delta = -dy; break;\n            case 1:                                             break;\n            case 2: hor_line_delta =  dx; ver_line_delta =  dy; break;\n        }\n\n        gl_Position = vec4(min_xy[0] - hor_line_delta, min_xy[1] - ver_line_delta, 0, 1);\n        gs_fs_color = vs_gs_color[N_VERTEX0];\n        EmitVertex();\n        gl_Position = vec4(min_xy[0] - hor_line_delta, max_xy[1] + ver_line_delta, 0, 1);\n        gs_fs_color = vs_gs_color[N_VERTEX0];\n        EmitVertex();\n        EndPrimitive();\n        gl_Position = vec4(max_xy[0] + hor_line_delta, min_xy[1] - ver_line_delta, 0, 1);\n        gs_fs_color = vs_gs_color[N_VERTEX1];\n        EmitVertex();\n        gl_Position = vec4(min_xy[0] - hor_line_delta, min_xy[1] - ver_line_delta, 0, 1);\n        gs_fs_color = vs_gs_color[N_VERTEX1];\n        EmitVertex();\n        EndPrimitive();\n        gl_Position = vec4(max_xy[0] + hor_line_delta, max_xy[1] + ver_line_delta, 0, 1);\n        gs_fs_color = vs_gs_color[N_VERTEX2];\n        EmitVertex();\n        gl_Position = vec4(max_xy[0] + hor_line_delta, min_xy[1] - ver_line_delta, 0, 1);\n        gs_fs_color = vs_gs_color[N_VERTEX2];\n        EmitVertex();\n        EndPrimitive();\n        gl_Position = vec4(min_xy[0] - hor_line_delta, max_xy[1] + ver_line_delta, 0, 1);\n        gs_fs_color = vec4(vs_gs_color[N_VERTEX0].r, vs_gs_color[N_VERTEX1].g, vs_gs_color[N_VERTEX2].b, vs_gs_color[N_VERTEX0].a);\n        EmitVertex();\n        gl_Position = vec4(max_xy[0] + hor_line_delta, max_xy[1] + ver_line_delta, 0, 1);\n        gs_fs_color = vec4(vs_gs_color[N_VERTEX0].r, vs_gs_color[N_VERTEX1].g, vs_gs_color[N_VERTEX2].b, vs_gs_color[N_VERTEX0].a);\n        EmitVertex();\n        EndPrimitive();\n    }\n}\n";
