pub(super) const TRIANGLES_GEOMETRYSHADERCODE_GS_POINTS_CODE: &str = "uniform ivec2 renderingTargetSize;\n\nin  vec4 vs_gs_color[N_VERTICES];\nout vec4 gs_fs_color;\n\nvoid main()\n{\n    float dx = 2.0 / float(renderingTargetSize.x);\n    float dy = 2.0 / float(renderingTargetSize.y);\n\n    for (int n = 0; n < 3 ; ++n)\n    {\n        int vertex_index = (n == 0) ? N_VERTEX0 : \n                           (n == 1) ? N_VERTEX1 : \n                                      N_VERTEX2;\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(-dx, -dy, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(0, -dy, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(dx, -dy, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(-dx, 0, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(0, 0, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(dx, 0, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(-dx, dy, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(0, dy, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n        gl_Position = vec4(gl_in[vertex_index].gl_Position.xyz, 1) + vec4(dx, dy, 0, 0);\n        gs_fs_color = vs_gs_color[vertex_index];\n        EmitVertex();\n    }\n}\n";
