pub(super) const TRIANGLES_GEOMETRYSHADERCODE_GS_TRIANGLES_CODE: &str = "uniform ivec2 renderingTargetSize;\n\nin  vec4 vs_gs_color[N_VERTICES];\nout vec4 gs_fs_color;\n\nvoid main()\n{\n    float dx = 2.0 / float(renderingTargetSize.x);\n    float dy = 2.0 / float(renderingTargetSize.y);\n\n    vec4 v0 = gl_in[N_VERTEX0].gl_Position;\n    vec4 v1 = gl_in[N_VERTEX1].gl_Position;\n    vec4 v2 = gl_in[N_VERTEX2].gl_Position;\n    vec4 a  = v0;\n    vec4 b;\n    vec4 c;\n    vec4 d;\n\n    if (abs(v1.w) >= 1.0)\n    {\n        a = v1;\n    \n        if (abs(v0.x - a.x) < dx)\n        {\n            b = v0;\n            c = v2;\n        }\n        else\n        {\n            b = v2;\n            c = v0;\n        }\n    }\n    else\n    if (abs(v2.w) >= 1.0)\n    {\n        a = v2;\n    \n        if (abs(v0.x - a.x) < dx)\n        {\n            b = v0;\n            c = v1;\n        }\n        else\n        {\n            b = v1;\n            c = v0;\n        }\n    }\n    else\n    {\n        if (abs(v1.x - a.x) < dx)\n        {\n            b = v1;\n            c = v2;\n        }\n        else\n        {\n            b = v2;\n            c = v1;\n        }\n    }\n    \n    d = (b + c) * vec4(0.5);\n    gl_Position = vec4(a.xyz, 1);\n    gs_fs_color = vs_gs_color[N_VERTEX0];\n    EmitVertex();\n\n    gl_Position = vec4(b.xyz, 1);\n    gs_fs_color = vs_gs_color[N_VERTEX0];\n    EmitVertex();\n\n    gl_Position = vec4(d.xyz, 1);\n    gs_fs_color = vs_gs_color[N_VERTEX0];\n    EmitVertex();\n    EndPrimitive();\n    gl_Position = vec4(a.xyz, 1);\n    gs_fs_color = vec4(2.0, 1.0, 1.0, 1.0) * vs_gs_color[N_VERTEX2];\n    EmitVertex();\n\n    gl_Position = vec4(c.xyz, 1);\n    gs_fs_color = vec4(2.0, 1.0, 1.0, 1.0) * vs_gs_color[N_VERTEX2];\n    EmitVertex();\n\n    gl_Position = vec4(d.xyz, 1);\n    gs_fs_color = vec4(2.0, 1.0, 1.0, 1.0) * vs_gs_color[N_VERTEX2];\n    EmitVertex();\n    EndPrimitive();\n}\n";
